// Smash Remix 2.0.1: "stages-remix-ranked" game option (server only)
//
// GENERATED by smash-remix-2.0.1-gen-stage-options.py from the ROM; edit the
// stage list there and regenerate. Ranked stages, as the ranked module set
// them up (SmashRemix.cpp, stage list kRemixStages):
//   0x06 Dream Land               hazard mode 0
//   0x6F Goomba Road              hazard mode 0
//   0xA4 Pokemon Stadium 2        hazard mode 0
//   0x2D Pokemon Stadium          hazard mode 0
// Stage select is on, on Remix's tournament layout (ranked-rules sets
// Toggles.entry_sss_layout to TOURNAMENT): one page with these stages, then
// Random on every other icon (exactly what the module's build_stage_select
// wrote). Random picks among these stages only.
// Each pick applies the stage's hazard mode from Stages.tournament_hazard_mode_table
// (hovering a stage on the tournament layout, or Random's pick).
//
// Needs ranked-rules (tournament layout, and no settings shortcut on stage select).
//
// Assemble over a copy of the ROM to check the JSON (see smash-remix-2.0.1-ranked-rules.asm):
//   bass.exe -o patched.z64 smash-remix-2.0.1-stages-remix-ranked.asm
//
// ROM: Smash_Remix_2.0.1.z64, MD5 2B2D6B295106C54216B7FC7A2F14346E.

arch n64.cpu
endian msb

constant r0(0)
constant t0(8)

macro seek(variable ram) {
    origin ram - 0x80400000 + 0x02C00000
    base ram
}
macro seek_logo(variable ram) {
    origin ram - 0x7FFB2E40
    base ram
}
macro toggle(variable entry, variable value) {
    seek(entry + 4)
    dw value
}

